// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool success,) = address(c).call{value: 1 ether}("");
        require(success);

        address alice = address(0x1234);
        vm.deal(alice, 0);
        vm.prank(alice);

        bool ok;
        try c.withdrawAll(alice) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
